"use client";

import React from "react";

import { useMotionActivity } from "../hooks/useMotionActivity";
import { clampFinite } from "../utils/numbers";

import styles from "./KineticTextRamp.module.css";

export type KineticTextRampTrigger = "always" | "hover" | "mount";

export interface KineticTextRampProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "children"> {
  children: string;
  trigger?: KineticTextRampTrigger;
  rows?: number;
  durationMs?: number;
  /** Freeze motion; offscreen, hidden tabs, and reduced motion also pause it. */
  paused?: boolean;
  delayMs?: number;
}

export function KineticTextRamp({
  children,
  trigger = "always",
  rows = 8,
  durationMs = 9000,
  delayMs = 0,
  paused = false,
  className = "",
  style,
  ...props
}: KineticTextRampProps) {
  const { ref, running } = useMotionActivity(paused);
  const safeRows = Math.floor(clampFinite(rows, 4, 14, 8));
  const safeDuration = clampFinite(durationMs, 1, 120000, 9000);
  const safeDelay = clampFinite(delayMs, -120000, 120000, 0);
  const mergedStyle = {
    ...style,
    ["--kinetic-text-ramp-rows" as string]: safeRows,
    ["--kinetic-text-ramp-duration" as string]: `${safeDuration}ms`,
    ["--kinetic-text-ramp-delay" as string]: `${safeDelay}ms`,
  } as React.CSSProperties;

  return (
    <div
      ref={ref}
      data-running={running ? "true" : "false"}
      {...props}
      className={`${styles.root} ${className}`.trim()}
      data-trigger={trigger}
      role="img"
      aria-label={props["aria-label"] ?? children}
      style={mergedStyle}
    >
      <div className={styles.viewport} aria-hidden="true">
        <div className={styles.plane}>
          <div className={styles.track}>
            {[0, 1].map((loop) => (
              <div className={styles.loop} key={loop}>
                {Array.from({ length: safeRows }, (_, index) => (
                  <span className={styles.row} key={index}>
                    {children}
                  </span>
                ))}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

.root {
  box-sizing: border-box;
  container-type: inline-size;
  position: relative;
  display: block;
  width: 100%;
  min-height: 14rem;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  background: #1738ef;
  color: #fff;
  isolation: isolate;
}

.viewport {
  position: absolute;
  inset: -11% -17% -33%;
  overflow: hidden;
  perspective: 34rem;
  perspective-origin: 50% 10%;
}

.plane {
  position: absolute;
  inset: 0;
  transform: rotateX(48deg) scale(1.22);
  transform-origin: 50% 4%;
  transform-style: preserve-3d;
}

.track {
  position: absolute;
  inset: 0 0 auto;
  display: flex;
  flex-direction: column;
  height: 200%;
  animation-duration: var(--kinetic-text-ramp-duration, 9000ms);
  animation-delay: var(--kinetic-text-ramp-delay, 0ms);
  animation-timing-function: linear;
  animation-fill-mode: both;
  will-change: transform;
}

.root[data-trigger="always"] .track,
.root[data-trigger="mount"] .track {
  animation-name: textRampScroll;
}

.root[data-trigger="always"] .track {
  animation-iteration-count: infinite;
}

.root[data-trigger="mount"] .track {
  animation-iteration-count: 1;
}

.root[data-trigger="hover"]:hover .track,
.root[data-trigger="hover"]:focus-within .track {
  animation-name: textRampScroll;
  animation-iteration-count: infinite;
}

.loop {
  display: grid;
  flex: 0 0 50%;
  grid-template-rows: repeat(var(--kinetic-text-ramp-rows, 8), minmax(0, 1fr));
}

.row {
  display: grid;
  place-items: center;
  overflow: hidden;
  font-family: Impact, Haettenschweiler, "Arial Narrow Bold", sans-serif;
  font-size: clamp(2.4rem, 14cqw, 10rem);
  font-style: italic;
  font-weight: 900;
  line-height: 0.86;
  letter-spacing: -0.065em;
  text-align: center;
  text-transform: uppercase;
  white-space: nowrap;
  text-shadow:
    0.035em 0.035em 0 #101116,
    0.07em 0.07em 0 #101116,
    0.105em 0.105em 0 #101116,
    0.14em 0.14em 0 #101116,
    0.175em 0.175em 0 #101116;
}

@keyframes textRampScroll {
  from {
    transform: translate3d(0, 0, 0);
  }

  to {
    transform: translate3d(0, -50%, 0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .track {
    animation: none !important;
    transform: none;
    will-change: auto;
  }
}

.root[data-running="false"], .root[data-running="false"] * { animation-play-state: paused !important; }
